{"file_path": "/tmp/grid.py", "content": "from PIL import Image, ImageDraw
img = Image.open('radiograph.jpg').convert('RGB')
W, H = img.size
d = ImageDraw.Draw(img)
# vertical gridlines every 100 px, horizontal every 100 px, labeled
for x in range(0, W, 100):
    d.line([(x, 0), (x, H)], fill=(255, 0, 0), width=1)
for y in range(0, H, 100):
    d.line([(0, y), (W, y)], fill=(255, 0, 0), width=1)
for x in range(0, W, 100):
    d.text((x + 2, 5), str(x), fill=(255, 0, 0))
for y in range(0, H, 100):
    d.text((5, y + 2), str(y), fill=(0, 0, 255))
img.save('/tmp/grid.jpg', quality=90)
print('saved')
